import{_ as e,o as r,c as o,a6 as s}from"./chunks/framework.CCKCzdWs.js";const u=JSON.parse('{"title":"Editor commands","description":"Every command of the Piwi extension for VS Code and of the Piwi plugin for the JetBrains IDEs: connection, runs, the failures, recording, run control, code at a stop, sharing live and agents, with what each does.","frontmatter":{"title":"Editor commands","description":"Every command of the Piwi extension for VS Code and of the Piwi plugin for the JetBrains IDEs: connection, runs, the failures, recording, run control, code at a stop, sharing live and agents, with what each does.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/editor-commands.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/editor-commands.html"}],["meta",{"property":"og:title","content":"Editor commands | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Every command of the Piwi extension for VS Code and of the Piwi plugin for the JetBrains IDEs: connection, runs, the failures, recording, run control, code at a stop, sharing live and agents, with what each does."}]]},"headers":[],"relativePath":"reference/editor-commands.md","filePath":"reference/editor-commands.md","lastUpdated":1794674675000}'),n={name:"reference/editor-commands.md"};function a(i,t,d,h,g,l){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="editor-commands" tabindex="-1">Editor commands <a class="header-anchor" href="#editor-commands" aria-label="Permalink to &quot;Editor commands&quot;">​</a></h1><p>Every command the two editors offer, by what it acts on. VS Code lists them in the command palette under <strong>Piwi:</strong>; a JetBrains IDE lists them under <strong>Tools → Piwi</strong> and in <strong>Find Action</strong>, says caret for cursor and project for window, and shows a toggle&#39;s state with a check mark. A row that names one editor is that editor&#39;s alone. Both editors give <code>Ctrl+Shift+Alt+K</code> to Run the test at the cursor, <code>Ctrl+Shift+Alt+F</code> to Re-run the failing tests and <code>Ctrl+Shift+Alt+R</code> to Record here… and Stop recording (<code>Cmd</code> on macOS); a run&#39;s controls take the debugger&#39;s keys (<a href="/features/editor-run-control.html#the-controls">The controls</a>).</p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Connect…</strong>, <strong>Piwi: Disconnect</strong></td><td>Choose the desktop app or an instance and its project, or forget them: <a href="/features/editor-connection.html">Editor connection</a></td></tr><tr><td><strong>Piwi: Open settings</strong></td><td>Piwi&#39;s settings: the instance and the project</td></tr><tr><td><strong>Piwi: Read the instance and the configs again</strong></td><td>Fetch the indexes and the latest run again and read the Playwright configs; in a JetBrains IDE, search the project for configs again and start a stopped editor service</td></tr><tr><td><strong>Piwi: Restart the editor service</strong></td><td>Stop the editor service and start it again</td></tr><tr><td><strong>Piwi: Open the log</strong></td><td>The editor service&#39;s log: its starts and ends, its errors and the requests that failed</td></tr><tr><td><strong>Piwi: Open the Piwi menu</strong></td><td>VS Code: the status bar item&#39;s menu, which a JetBrains IDE opens with a click on its item: <a href="/features/editor-status-bar.html">The editor&#39;s status bar</a></td></tr><tr><td><strong>Piwi: Node.js settings…</strong></td><td>JetBrains: choose the Node.js the editor service starts with</td></tr><tr><td><strong>Piwi: Get started</strong></td><td>VS Code: open the walkthrough</td></tr><tr><td><strong>Piwi: Open the documentation</strong></td><td>Open this site in the browser: <a href="/features/editors.html">Editor extensions</a> from VS Code, <a href="/features/jetbrains.html">JetBrains plugin</a> from a JetBrains IDE</td></tr></tbody></table><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Run the test at the cursor</strong></td><td>Run the test whose <code>test(…)</code> call holds the cursor: <a href="/features/editor-runs.html#run-tests">Run tests</a></td></tr><tr><td><strong>Piwi: Verify the test at the cursor ×3</strong></td><td>Run it three times without retries and say how many runs passed</td></tr><tr><td><strong>Piwi: Run this spec</strong></td><td>Run every test of the spec as it stands</td></tr><tr><td><strong>Piwi: Run the tests that reach this file</strong></td><td>Run the tests that reach the active file through <a href="/features/code-reach.html">code reach</a></td></tr><tr><td><strong>Piwi: Run a saved selection…</strong></td><td>Run a saved <a href="/features/test-selection.html">selection</a></td></tr><tr><td><strong>Piwi: Show the test&#39;s actions…</strong></td><td>VS Code: the actions of the test at the cursor, as its gutter offers them</td></tr><tr><td><strong>Piwi: Re-run the failing tests</strong></td><td>Run every test that still fails: <a href="/features/editor-runs.html#re-run-the-failing-tests">Re-run the failing tests</a></td></tr><tr><td><strong>Piwi: Turn headed runs on or off</strong></td><td>Run every test Piwi starts in this window headed, or headless: <a href="/features/editor-runs.html#how-a-run-starts">How a run starts</a></td></tr><tr><td><strong>Piwi: Hold failures from each run&#39;s start…</strong></td><td>Auto, On or Off: whether a failed test of each run waits at its line for an answer</td></tr><tr><td><strong>Piwi: Run options…</strong></td><td>VS Code: choose between the two above</td></tr></tbody></table><h2 id="the-failures-and-the-dashboard" tabindex="-1">The failures and the dashboard <a class="header-anchor" href="#the-failures-and-the-dashboard" aria-label="Permalink to &quot;The failures and the dashboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Refresh the latest run</strong></td><td>Read the latest run and its failures again, and none of the indexes</td></tr><tr><td><strong>Piwi: Open in dashboard</strong></td><td>Open the selected failure, run or test in the dashboard; from the palette, this file&#39;s test, else the latest run</td></tr><tr><td><strong>Piwi: Open the latest run</strong></td><td>Open the run the status bar shows</td></tr><tr><td><strong>Piwi: Compare with…</strong></td><td>Choose the run the failures are read against: <a href="/features/editor-status-bar.html#compare-with-another-run">Compare with another run</a></td></tr><tr><td><strong>Piwi: Group the failures by…</strong></td><td>File, cluster or owner, or a flat list: <a href="/features/editor-failures.html#the-failures-view">The failures view</a></td></tr><tr><td><strong>Piwi: Follow the active editor</strong>, <strong>Piwi: Stop following the active editor</strong></td><td>VS Code: select the active file&#39;s first failure in the failures view, or stop</td></tr><tr><td><strong>Piwi: Open the failures</strong></td><td>JetBrains: open the Piwi tool window&#39;s failures</td></tr><tr><td><strong>Piwi: Show the run&#39;s flaky tests</strong></td><td>Open the failures view on the run&#39;s <a href="/features/flaky-tests.html">flaky tests</a></td></tr><tr><td><strong>Piwi: Show or hide the coverage marks</strong></td><td>The <a href="/features/editor-coverage.html">coverage marks</a> of the lines the tests ran</td></tr></tbody></table><p>A failure&#39;s menu in the failures view adds <strong>Run this test</strong>, <strong>Debug this failure</strong>, <strong>Verify the test ×3</strong>, <strong>Go to the test</strong>, <strong>Open the trace</strong>, <strong>Open the screenshot</strong>, <strong>Copy context for agent</strong>, <strong>Reproduce in the desktop app</strong>, <strong>Find the breaking commit in the desktop app</strong> and, on a flaky test in VS Code, <strong>Look into this flake…</strong>: <a href="/features/editor-failures.html">Failures in the editor</a>.</p><h2 id="recording" tabindex="-1">Recording <a class="header-anchor" href="#recording" aria-label="Permalink to &quot;Recording&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Record here…</strong></td><td>Record at the cursor, in a browser your project&#39;s Playwright opens: <a href="/features/editor-recording.html">Record tests from the editor</a></td></tr><tr><td><strong>Piwi: Record a new test file…</strong></td><td>Create a spec and record into it; in a JetBrains IDE, the <strong>New</strong> menu&#39;s <strong>Playwright test (recorded)…</strong> too</td></tr><tr><td><strong>Piwi: Stop recording</strong>, <strong>Piwi: Pause recording</strong>, <strong>Piwi: Resume recording</strong></td><td>Control the recording in progress</td></tr><tr><td><strong>Piwi: Go to the recorded lines</strong></td><td>JetBrains: open the lines the recording in progress writes</td></tr><tr><td><strong>Piwi: Pair with Piwi Picker</strong></td><td>Copy the address <a href="/features/editor-recording.html#send-from-piwi-picker">Piwi Picker sends to</a></td></tr></tbody></table><h2 id="run-control" tabindex="-1">Run control <a class="header-anchor" href="#run-control" aria-label="Permalink to &quot;Run control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Pause the run</strong>, <strong>Piwi: Resume the run</strong>, <strong>Piwi: Step to the next call</strong>, <strong>Piwi: Run to the cursor</strong>, <strong>Piwi: Finish the test</strong>, <strong>Piwi: End the test</strong>, <strong>Piwi: Stop the run</strong></td><td><a href="/features/editor-run-control.html">Pause and step from the editor</a></td></tr><tr><td><strong>Piwi: Go to the stopped line</strong>, <strong>Piwi: Show the paused page</strong></td><td>Open the line a test is stopped at, or an image of its page</td></tr><tr><td><strong>Piwi: Turn hold failures on or off for the run</strong></td><td>Whether a failed test the pause bar does not show waits at its line, in this run</td></tr><tr><td><strong>Piwi: Watch a worker&#39;s test</strong>, <strong>Piwi: Pause and watch a worker&#39;s test</strong>, <strong>Piwi: Open the trace so far</strong></td><td><a href="/features/watch-running-test.html">Watch a local test</a></td></tr><tr><td><strong>Piwi: Show the stopped test&#39;s browser</strong></td><td>Bring a headed run&#39;s browser window to the front</td></tr><tr><td><strong>Piwi: Share the stopped test&#39;s browser with Playwright tools</strong></td><td><a href="/features/editor-run-control.html#share-with-playwright-tools">Share with Playwright tools</a></td></tr><tr><td><strong>Piwi: Open the page of a run of this window</strong></td><td>The page of a run this window started or follows, on the instance or the desktop app</td></tr><tr><td><strong>Piwi: Open the branch&#39;s run in progress</strong></td><td>VS Code: open the run of the branch the instance is receiving: <a href="/features/watch-a-run.html">Follow a run</a></td></tr></tbody></table><h2 id="code-at-a-stop" tabindex="-1">Code at a stop <a class="header-anchor" href="#code-at-a-stop" aria-label="Permalink to &quot;Code at a stop&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Pick a locator at the stop</strong>, <strong>Piwi: Record at the stop</strong>, <strong>Piwi: Assert at the stop</strong>, <strong>Piwi: Assert a region at the stop</strong>, <strong>Piwi: Mock a request at the stop…</strong></td><td>What the stop&#39;s own controls call Pick a locator, Record, Assert, Assert a region and Mock a request: <a href="/features/editor-stop-code.html">Code from a pause</a></td></tr><tr><td><strong>Piwi: Write code at the stop…</strong></td><td>VS Code: choose one of them</td></tr></tbody></table><h2 id="share-live" tabindex="-1">Share live <a class="header-anchor" href="#share-live" aria-label="Permalink to &quot;Share live&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Share the run live on the team instance</strong>, <strong>Piwi: Stop sharing the run live</strong></td><td><a href="/features/share-live.html">Share a local run live</a></td></tr><tr><td><strong>Piwi: Share this window&#39;s runs live until I stop</strong>, <strong>Piwi: Stop sharing this window&#39;s runs live</strong></td><td>Every run of this window, from now on</td></tr><tr><td><strong>Piwi: Shared live: open the run page, copy its link or stop sharing…</strong></td><td>VS Code: the menu of the status bar&#39;s live item</td></tr></tbody></table><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Piwi: Copy the MCP server configuration…</strong></td><td>Piwi&#39;s <a href="/features/editors.html#piwi-s-mcp-server-for-the-agent">MCP server</a> for an agent</td></tr><tr><td><strong>Piwi: Copy the runs&#39; MCP server configuration for agents…</strong>, <strong>Piwi: Copy the runs&#39; MCP server configuration for Claude Code or Cursor</strong>, <strong>Piwi: Reset the runs&#39; MCP server token</strong></td><td><a href="/features/agent-run-control.html">Run control for agents</a>; the second is JetBrains&#39;</td></tr></tbody></table><p>The lines above the code and the quick fixes also run commands no menu lists: <strong>Run tests</strong>, <strong>Run a command</strong>, <strong>Copy text</strong> and <strong>Reproduce, bisect or run Flake Lab in the desktop app</strong>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/editors.html">Editor extensions</a>: what the extensions show, and how they connect.</li><li><a href="/features/jetbrains.html">JetBrains plugin</a>: what the plugin needs and draws differently.</li></ul>',22)])])}const f=e(n,[["render",a]]);export{u as __pageData,f as default};
